import hashlib
import json

def snapshot(names):
    result = {}
    for name in names:
        with open(name, "rb") as f:
            result[name] = hashlib.sha256(f.read()).hexdigest()
    return result

def compare(old, new):
    added = sorted(set(new) - set(old))
    removed = sorted(set(old) - set(new))
    modified = sorted(n for n in set(old) & set(new) if old[n] != new[n])
    return added, removed, modified

with open("baseline.json", encoding="utf-8") as f:
    old = json.load(f)
new = snapshot(["a.txt", "b.txt", "d.txt"])
added, removed, modified = compare(old, new)
if not (added or removed or modified):
    print("INTEGRITY OK")
else:
    for n in modified:
        print("MODIFIED " + n)
    for n in added:
        print("ADDED " + n)
    for n in removed:
        print("REMOVED " + n)
